--初始化boss信息
function WorldBossComponent:InitialBossInfo(jsonData)
    if not jsonData then
        return
    end

    self._remainTime = checkNumber(jsonData.worldBossStartTime) - 2    --服务器回来的时间直接减2 有个时间差外加timedown的一秒
    self._curBossPlanId = checkNumber(jsonData.worldBossScheduleId)

    self._lastWeekRankList = {}
    local lastWeekListInfo = jsonData.worldBossLastRankInfo
    if lastWeekListInfo then
        for k, v in pairs(lastWeekListInfo) do
            local dojo = RankingListDojo.New()
            dojo:Fill(v)
            dojo.rankNum = checkNumber(k)
            table.insert(self._lastWeekRankList, dojo)
        end
    end
    
    if self._curBossPlanId > 0 then
        --[[
        local lastWeekListInfo = jsonData.worldBossLastRankInfo
        if lastWeekListInfo then
            for k, v in pairs(lastWeekListInfo) do
                local dojo = RankingListDojo.New()
                dojo:Fill(v)
                dojo.rankNum = checkNumber(k)
                table.insert(self._lastWeekRankList, dojo)
            end
        end
        ]]
        
        self:InitDurationTime(self._curBossPlanId)
        self._curBossDurTime = self:GetBossDurationTime()
        self:StartTimeDown()
    end
    -- print(table.dump(jsonData))
end

function WorldBossComponent:WorldBossInitInfo(cb)
    GameUtils.Request(Interfaces.WorldBossInit, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            printError(checkString(table.dump(response)))
            return
        end
        local jsonData = response.data
        self._historyMaxHurt = checkNumber(jsonData.historyMaxHurt)
        local t = jsonData.hurtDrawRewardId
        self._hurtDrawRewards = {}
        for k, v in pairs(t) do
            self._hurtDrawRewards[checkString(v)] = 1
        end
        if cb then
            cb()
        end
    end)
end

--世界Boos初始化
function WorldBossComponent:WorldBossInitReq(cb)
    GameUtils.Request(Interfaces.WorldBossInit, {}, function(request, response)
