--抽取Buff
function WorldBossComponent:WorldBossExtractBuffReq(cb)
    GameUtils.Request(Interfaces.WorldBossBuff, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._curBuffs = jsonData.buffInfo
        if self._freeBuyBuffNum > 0 then
            self._freeBuyBuffNum = self._freeBuyBuffNum - 1
        end

        Events.Broadcast(Constants.EventNames.WorldBossBuffChange, nil)
        if cb then
            cb()
        end
    end)
end

--领取伤害奖励
function WorldBossComponent:WorldBossdrawHurtRewardReq(rewardId, cb)
    GameUtils.Request(Interfaces.WorldBossdrawHurtReward, {rewardId = rewardId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsondata = response.data
        local rewardData = jsondata.rewards

        if rewardId then
            self._hurtDrawRewards[checkString(rewardId)] = 1
            GoodsUtils.DrawRewards(rewardData)
        else
            --一键领取
            GoodsUtils.DrawRewards(rewardData)
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData } })
        end

        if cb then
            cb(clone(rewardData))
        end
    end)
end

