--排行榜
function WorldBossComponent:WorldBossRankReq()
    GameUtils.Request(Interfaces.WorldBossRank, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        ---@type RankingListDojo
        local RankingListDojo = import("Game.Dojo.RankingListDojo")

        local jsonData = response.data
        local info = jsonData.rankInfo
        local t = {}
        for k, v in pairs(info) do
            local dojo = RankingListDojo.New()
            dojo:Fill(v)
            dojo.rankNum = checkNumber(k)
            table.insert(t, dojo)
        end

        local meRankData = {
            rankNum = self._curRankInfo.ranking,
            hurt = self._curRankInfo.hurt,
        }

        local percentageRank = checkNumber(jsonData.percentageRank)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIWorldBossPlayerRankingsDialog, parameters = {data = t, percentageRank = percentageRank, rankMeData = meRankData}}, {
            {id = Constants.UITypeIds.UIWorldBossMainDialog}
        })
    end)
end

