--设置当前的排名
function WorldBossComponent:SetCurRankInfo(data)
    if not data then
        return
    end

    if (checkNumber(data.ranking) > checkNumber(self._curRankInfo.ranking)) and (checkNumber(self._curRankInfo.ranking) ~= 0) then
        return
    elseif checkNumber(data.ranking) == checkNumber(self._curRankInfo.ranking) then
        if (checkNumber(data.hurt) < checkNumber(self._curRankInfo.hurt)) and (checkNumber(self._curRankInfo.hurt) ~= 0) then
            return
        end
    end
    self._curRankInfo = data
    GameUtils.SetRedPointNum(Constants.RedPointConst.WorldBossReward, self:IsCanDrawReward())
end

