function WorldBossComponent:IsOpen()
    if checkNumber(self._remainTime) <= 0-1 then
        return true
    end
    return false
end

--是否领取了奖励
function WorldBossComponent:IsDrawReward(id)
    if not self._hurtDrawRewards then
        return false
    end
    return checkNumber(self._hurtDrawRewards[checkString(id)]) == 1
end

--开始倒计时
function WorldBossComponent:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id, Elapsed)
        self._remainTime = self._remainTime - Elapsed
        --开门了
        if self._remainTime == 0-2 then
            Events.Broadcast(Constants.EventNames.WorldBossBegin, nil)
        end
        --如果结束了
        if (self._remainTime -2) < self:GetBossDurationTime() * -1 then
            self._remainTime = CountDownTime    --赋值最大等待下一次更新
            self._isNeedRefresh = true
            Events.Broadcast(Constants.EventNames.WorldBossEnd, nil)
        end
    end, CountDownTime, false, true)
end

---GetBossDurationTime 获取持续时间
function WorldBossComponent:GetBossDurationTime()
    return checkNumber(self._curBossDurTime)
end

---InitDurationTime 初始化boss持续时间
function WorldBossComponent:InitDurationTime(bossPlanId)
    bossPlanId = checkNumber(bossPlanId)
    if bossPlanId == 0 then
        self._curBossDurTime = 0
        return
    end
    local vo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(bossPlanId)
    if not vo then
        self._curBossDurTime = 0
        return
    end    
    
    local fT = date(vo.startDay)
    local tT = date(vo.endDay)

    if not fT or not tT then
        self._curBossDurTime = 0
        return
    end

    local timeSpan = date.diff(tT, fT)
    if not timeSpan then
        self._curBossDurTime = 0
        return 
    end
    self._curBossDurTime = timeSpan:spanseconds()
end

--获取boss场景
function WorldBossComponent:GetWorldBossSceneData()
    if self._sceneData then
        return self._sceneData
    end
    
    local vo  = QuestConfMgr:GetInstance():GetWorldBossPlanVo(self._curBossPlanId)
    if not vo then
        return nil
    end
    self._sceneData = {
        id = Constants.IdSceneSetting17,
        name = 'BFightmap03',
        path = "BFightmap03.unity",
        position = Vector3(0, 0, 0),
        rotation = Vector3(0, 0, 0)
    }
    return self._sceneData
end

--进入世界boss
function WorldBossComponent:OnWorldBossEnter()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id14)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id14))
        return
    end

    --[[
    --如果需要更新信息
    if self._isNeedRefresh then
        self:WorldBossInitReq(function()
            self:WorldBossEnter()
        end)
    else
        self:WorldBossEnter()
    end
    ]]
    self:OpenWorldBossScene()
end

function WorldBossComponent:RefreshWorldBossInfo(cb)
    if self._isNeedRefresh then
        self:WorldBossInitReq(function()
            local isOpen = self:IsOpen()
            if isOpen then
                self:WorldBossHomeReq(
                    function()
                        if cb then
                            cb()
                        end
                    end
                )
            else
                if cb then
                    cb()
                end
            end
        end)
    else
        local isOpen = self:IsOpen()
        if isOpen then
            self:WorldBossHomeReq(
                function()
                    if cb then
                        cb()
                    end
                end
            )
        else
            self:WorldBossInitInfo(function()
                if cb then
                    cb()
                end
            end)
        end
    end
end

function WorldBossComponent:WorldBossEnter()
    local isOpen = self:IsOpen()
    if isOpen then
        self:WorldBossHomeReq(
            function()
                self:OpenWorldBossScene()
            end
        )
    else
        self:OpenWorldBossScene()
    end
end

--打开世界boss场景
function WorldBossComponent:OpenWorldBossScene()
    local t = {}
    local dialogs = CS.Engine.UI.UIModule.CurrentScreen.dialogs
    for _, dialog in pairs(dialogs) do
            table.insert(t, dialog.Argument)
    end

    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIWorldBossMainDialog}, t)
    --GameUtils.OpenLoadingPanel({id = Constants.UITypeIds.WorldBossEntry}, {{id = Constants.UITypeIds.UIWorldBossMainDialog, parameters = {}}}, Constants.LoadingType.WorldBoss, false)
end

--开始世界boss战斗  
function WorldBossComponent:WorldBossBattleBeging(levelId)
    if not self:IsOpen() then
        GameUtils.Toast(localize("活动时间已关闭"))
        return 
    end

    local scr
    --[[
    --清掉当前所有的ui
    local dialogs = CS.Engine.UI.UIModule.CurrentScreen.dialogs
    for i, dialog in pairs(dialogs) do
        CS.Engine.UI.UIModule.CloseDialog(dialog)
    end

    local WorldBossMgr = import('Game.UI.FightReady.UIWorldBoss.WorldBossMgr')
    WorldBossMgr:GetInstance():DestoryBossModel()
    WorldBossMgr:GetInstance():SetCamCinema(true)

    if IsNull(self.loader) then
        self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/WorldBoss/WorldBossLoadingNode.prefab", nil, true)
    end
    if self.loader.IsSuccess then
        local loadingNode = CfUtils.InstantiateGo(self.loader.ResultObject, CS.Engine.UI.UIModule.RootCanvas)
        if loadingNode then
            scr = CfUtils.GetLuaScr(loadingNode, "Game.UI.FightReady.UIWorldBoss.WorldBossLoadingNode")
        end
    end    
    ]]

    FightPreWarMgr:GetInstance():FightEnter(levelId, {loadingEnv = scr})
end

--是否有奖励可领取
function WorldBossComponent:IsCanDrawReward()
    local t = self:GetAllReward()
    if not t then
        return 0
    end

    local info = self:GetCurRankInfo()
    local meHurt = checkNumber(info.hurt)

    for k, v in pairs(self._hurtRewards) do
        if meHurt >= checkNumber(v.upperLimit) then
            if not self:IsDrawReward(v.id) then
                return 1
            end
        end
    end
    return 0
end

function WorldBossComponent:GetAllReward()
    if self._hurtRewards then
        return self._hurtRewards
    end

    local t = CfUtils.GetCfTable(AutoIds.IdSetting976)
    if not t then
        return {}
    end
    self._hurtRewards = {}
    local WorldBossHurtRewardVo = import("Game.Setting.Vo.WorldBossHurtRewardVo")
    for k, v in pairs(t) do
        local vo = WorldBossHurtRewardVo.New()
        vo:FillVo(v)
        table.insert(self._hurtRewards, vo)
    end 
    return self._hurtRewards
end

function WorldBossComponent:ReleaseLoad()
    if not isNull(self.loader) then
        self.loader:Release(true)
        self.loader = nil
    end
end

return WorldBossComponent